arguments.cmd:
ls -A1 /challenge/inhere/area10/.records/
echo "---- python xattr check ----"
which python3 python 2>/dev/null
python3 - <<'EOF' 2>/dev/null || echo "no python3"
import os
for root, dirs, files in os.walk('/challenge/inhere'):
    for f in files:
        p = os.path.join(root, f)
        try:
            xa = os.listxattr(p)
            if xa:
                print(p, xa)
                for a in xa:
                    print(' ', a, os.getxattr(p, a))
        except OSError as e:
            print('ERR', p, e)
print("xattr scan done")
EOF

